# libxml2 — GNOME (cmake, static; our zlib/xz/iconv)
GIT_URL="https://gitlab.gnome.org/GNOME/libxml2.git"
BUILD() {
	cmake_driver "$SRC_ROOT/$NAME" "$BUILD_DIR/$NAME" \
		-DBUILD_SHARED_LIBS=OFF -DLIBXML2_WITH_PYTHON=OFF -DLIBXML2_WITH_ZLIB=ON \
		-DLIBXML2_WITH_LZMA=ON -DLIBXML2_WITH_ICONV=ON -DLIBXML2_WITH_HTTP=OFF \
		-DLIBXML2_WITH_FTP=OFF -DLIBXML2_WITH_TESTS=OFF -DLIBXML2_WITH_PROGRAMS=OFF \
		-DLIBXML2_WITH_LEGACY=ON
}
